<?php /** @var \App\Models\Repair $repair */ ?>
<section class="receipt"><header class="receipt-head"><div><span class="brand-auth">orion</span><h1><?= htmlspecialchars($repair->business->name) ?></h1><p><?= htmlspecialchars($repair->business->rif) ?><br><?= htmlspecialchars($repair->business->address) ?> · <?= htmlspecialchars($repair->business->phone) ?></p></div><div><span class="eyebrow">COMPROBANTE</span><h2>#<?= $repair->id ?></h2><p>Retiro límite: <?= $repair->due_date->format('d/m/Y') ?></p></div></header><dl class="receipt-meta"><dt>Cliente</dt><dd><?= htmlspecialchars($repair->client->name) ?></dd><dt>Cédula</dt><dd><?= htmlspecialchars($repair->client->cedula) ?></dd><dt>Descripción</dt><dd><?= htmlspecialchars($repair->description) ?></dd><dt>Total acordado</dt><dd>$<?= number_format((float)$repair->price,2,',','.') ?> <small>(ref. Bs. <?= number_format((float)$repair->price_ves,2,',','.') ?>)</small></dd><dt>Pagado</dt><dd>$<?= number_format($repair->getTotalPaid(),2,',','.') ?></dd><dt>Pago pendiente</dt><dd>$<?= number_format($repair->getRemainingAmount(),2,',','.') ?></dd><?php foreach($repair->payments as $payment): ?><dt><?= htmlspecialchars($payment->method) ?></dt><dd><?= \App\Support\PaymentMethod::isVes($payment->method) ? 'Bs. '.number_format((float)$payment->amount,2,',','.').' · tasa '.number_format((float)$payment->exchange_rate,2,',','.') : '$'.number_format((float)$payment->amount,2,',','.') ?></dd><?php endforeach ?></dl></section><script>print()</script>
